from __future__ import annotations

from typing import Any, Callable, Dict, Iterator, Self

__doc__ = """
Routine-level variable representations used by the code-generation backends.

This module bridges symbolic instruction-layer objects and concrete code
containers. It provides:

- :class:`Namespace`, which tracks allocated routine variables, temporary names,
  and instruction-variable assignments within nested scopes.
- :class:`LibRoutineVariable` and subclasses, which model routine arguments,
  locals, constants, imports, numeric literals, indexed accesses, and
  multiframe selectors.
- :class:`LibRoutineMultiFrame`, which represents loop- or kernel-driven index
  selectors that can later be expanded by compute resources into loops, thread
  IDs, block IDs, or combined structures.

The objects defined here are still language-neutral. Backends such as Fortran,
C, Python, NumPy, and CUDA specialize them further or wrap them in
backend-specific code containers.
"""

from ..toolbox.logger import GLOBAL_LOGGER as log


class Namespace:
    """Registry for routine variables, assignments, and scoped naming."""

    def __init__(self, parent: Namespace | None = None) -> None:
        # self._content: weakref.WeakValueDictionary[
        #     str, LibRoutineVariable
        # ] = weakref.WeakValueDictionary()
        # if this is weak, the namespace probably cannot remember temp variables that
        # have been set in another branch
        self._content = {}
        self._parent = parent
        self._assigned: Dict[type, Dict[str, LibRoutineVariable]] = {}
        # self._buffer = {}
        self._imports = {}

    def __contains__(self, element: object) -> bool:
        """Return whether a variable name or variable object is present."""
        if isinstance(element, LibRoutineVariable):
            element = element.name
        if element in self._content:
            return True
        if self._parent is not None:
            return self._parent.__contains__(element)
        return False

    def assign(self, ivariable_type, key, lvariable) -> None:
        """Assign an instruction-variable/key pair to a routine variable."""
        if ivariable_type not in self._assigned:
            self._assigned[ivariable_type] = {}
        self._assigned[ivariable_type][key] = lvariable
        log.debug(
            f"Namespace assigned {ivariable_type.get_name()}[{key}] -> {lvariable.name}",
            source=type(self).__name__,
        )

