class LibRoutineConstant(LibRoutineVariable):
    """Literal constant or constant array appearing in generated code."""

    # the idea of a constant is that this representative class also contains the associated values
    # and the constant is initialized somewhere

    # maybe introduce the is_set flag? -> no, instead set constants right within the same header
    # that they are defined in!
    # Also, some ideas of counters transfer, they have to be both initialized and handled in potentially
    # differnt places.

    _VAR_IDENTIFIER = "CONSTANT"
    _CLASS_BASE = "cns"

    def __init__(self, name, value, size=None, **kwargs):
        if size is None:
            if hasattr(value, "__iter__"):
                self._value = value
                size = len(value)
            else:
                self._value = value
        else:
            if not hasattr(value, "__iter__"):
                raise ValueError("value must be iterable.")
            if len(value) != size:
                raise ValueError("value size does not match the given size.")
            self._value = value

        super().__init__(name=name, size=size, **kwargs)

    @property
    def value(self):
        """access value"""
        if self.is_scalar:
            return self._value
        return list(self._value)

    @property
    def values(self):
        """access value"""
        if self.is_scalar:
            raise ValueError(
                "Cannot access multiple values of a scalar variable."
            )
        yield from self._value

    def append(self, value) -> None:
        """Append a value to a constant array."""
        if self.is_scalar:
            raise ValueError("Cannot append to a scalar variable.")
        self._value.append(value)
        self._size = len(self._value)


class Numeric(LibRoutineVariable):
    """
    representation of a numeric value of any form
    """

    DTYPE_LOOKUP = {
        complex: "c128",
        float: "f64",
        int: "i32",
    }

    DTYPE_HIERARCHY = {
        "i32": 1.0,
        "i64": 1.1,
        "f32": 2.0,
        "f64": 2.1,
        "c64": 3.0,
        "f128": 3.1,
    }

    def __init__(self, value, dtype=None, **kwargs) -> None:
        if isinstance(value, Numeric):
            self._value = value.value
            if dtype is None:
                dtype = value.dtype
        elif isinstance(value, LibRoutineVariable):
            raise ValueError(
                "cannot cast value from LibRoutineVariable to Numeric"
            )
        else:
            assert isinstance(
                value, (int, float, complex)
            ), "value must be numeric"
            self._value = value
        if dtype is None:
            dtype = type(self).DTYPE_LOOKUP[type(value)]
        self._is_complex = dtype[0] == "c"
        super().__init__(
            name=f"__NUMERIC_{dtype}_{value}",
            dtype=dtype,
            prefix=None,
            no_entry=True,
            **kwargs,
        )

    def _dtype_combine(self, other) -> str:
        """Return the more general dtype across ``self`` and ``other``."""
        if isinstance(other, Numeric):
            other_dtype = other.dtype
        elif isinstance(other, str):
            other_dtype = other
        else:
            other_dtype = type(self).DTYPE_LOOKUP[type(other)]
        if (
            type(self).DTYPE_HIERARCHY[self.dtype]
            < type(self).DTYPE_HIERARCHY[other_dtype]
        ):
            return other_dtype
        return self.dtype

    def _free_name(self):
        """discard the name in the namespace"""
        # do nothing here. Numerics have no namespace
        return

    def expr(self):
        if self._value < 0:
            return f"({self._value})"
        return f"{self._value}"

    @property
    def value(self):
        """access read-only attribute value"""
        return self._value

    @property
    def real(self):
        """access real value"""
        if self._is_complex:
            return self.value.real
        return self.value

    @property
    def imag(self):
        """access imaginary value"""
        if self._is_complex:
            return self.value.imag
        return None

    def __neg__(self):
        return type(self)(-self.value, dtype=self.dtype)

    def __mul__(self, other):
        if isinstance(other, Numeric):
            return type(self)(
                self.value * other.value, self._dtype_combine(other)
            )
        return type(self)(self.value * other, self._dtype_combine(other))

    def __add__(self, other):
        if isinstance(other, Numeric):
            return type(self)(
                self.value + other.value, self._dtype_combine(other)
            )
        return type(self)(self.value + other, self._dtype_combine(other))

    def __rmul__(self, other):
        return type(self)(other * self.value, self._dtype_combine(other))

    def __radd__(self, other):
        return type(self)(other + self.value, self._dtype_combine(other))

    def __sub__(self, other):
        if isinstance(other, Numeric):
            return type(self)(
                self.value - other.value, self._dtype_combine(other)
            )
        return type(self)(self.value - other, self._dtype_combine(other))

    def __truediv__(self, other):
        if isinstance(other, Numeric):
            return type(self)(
                self.value / other.value, self._dtype_combine(other)
            )
        return type(self)(self.value / other, self._dtype_combine(other))

    def __rsub__(self, other):
        return type(self)(other - self.value, self._dtype_combine(other))

    def __rtruediv__(self, other):
        return type(self)(other / self.value, self._dtype_combine(other))


class ValueAt(LibRoutineVariable):
    """Indexed access expression into another routine variable."""

    def __init__(self, variable, *offsets, simplify=False, **kwargs):
        self._variable = variable
        self._offsets = offsets

        super().__init__(
            name=None,
            size=None,
            namespace=Namespace(),
            dtype=variable.dtype,
            no_entry=True,
        )

        if variable.is_scalar:
            raise ValueError(
                f"Scalar {variable.name} does not provide index access"
            )

        self.simplify = simplify

    @property
    def plain(self):
        """access inner type"""
        return self._variable

    @property
    def name(self):
        return self._variable.name

    @staticmethod
    def process_offsets(
        *offsets,
        simplify=True,
        allow_strings=False,
    ):
        """Normalize integer and symbolic offsets into expression fragments."""
        offset_str_list = []
        offset_int = 0
        for offset in offsets:
            if isinstance(offset, int):
                if simplify:
                    offset_int += offset
                else:
                    offset_str_list.append(str(offset))
            elif isinstance(offset, LibRoutineVariable):
                offset_str_list.append(offset.expr())
            else:
                if allow_strings:
                    offset_str_list.append(str(offset))
                else:
                    raise ValueError(
                        f"offset {offset} is not an integer or LibRoutineVariable"
                    )
        if simplify:
            if offset_int > 0:
                offset_str_list.append(str(offset_int))
        if not offset_str_list:
            offset_str_list = ["0"]
        return offset_str_list

    def handle_dependencies(self) -> None:
        """Record dependencies introduced by symbolic offsets."""
        for offset in self._offsets:
            if isinstance(offset, LibRoutineVariable):
                self.depends_on(offset, recursive=True)

    def expr(self):
        """expression at offset"""

        offset_str_list = self.process_offsets(
            *self._offsets,
            simplify=self.simplify,
        )

        offset_str = " + ".join(offset_str_list)
        return self._variable.expr_at(offset_str)
        # return f"{self.name}[{offset_str}]"

    # def expr(self):
    #     if isinstance(self._offsets, int):
    #         return f"{self._variable.expr()}[{self._offsets}]"
    #     return f"{self._variable.expr()}[{self._offsets.expr()}]"


class LibRoutineMultiFrame(LibRoutineVariable):
    """
    An integer type variable made for iterating through an array or instructions,
    assuming order does not matter!
    """

    _VAR_IDENTIFIER = "MultiFrame"
    _CLASS_BASE = "mfr"

    local_variable_class = LibRoutineLocalVariable
    input_variable_class = LibRoutineInputVariable
    extra_offset = None

    # it can be associated with a range-like source, such as a loop or the grid/block ID on GPUs
    # maybe let it rise like other variables and introduce a "handled" flag that is true once the
    # looping structure has been enabled, which may still require proper initialization.
    # this is the counter object, not the lookup object. Each parallel environment will have
    # exactly one of these.

    def get_sort_group(self) -> int:
        """Place multiframe selectors after ordinary routine arguments."""
        return 99

    def __init__(
        self,
        max_value,
        min_value=0,
    ) -> None:
        super().__init__(
            size=None,
            namespace=None,
            prefix=None,
            status=2,
            dtype="i32",
        )

        # the container that the frame selector is attached to
        self._max_value = max_value
        self._min_value = min_value
        self._local = None

        # default value when branching needs to be suppressed
        self._default_value = min_value

    def recreate(self, namespace=None, key=None):
        """
        Recreate the selector in a new namespace, with caching per assignment.

        :param namespace: Namespace into which the recreated selector should be
            assigned.
        :param key: Optional assignment key used for caching in ``namespace``.
        :returns: Recreated or previously cached multiframe instance.
        """
        if namespace is None:
            # simply recreate.
            return type(self)(self.max_value, min_value=self.min_value)
        # try to find assignment in namespace
        lookup = namespace.find_assignment(
            self, key=key, exception_not_existing=False
        )
        # if not successful, ...
        if lookup is None:
            copy = type(self)(self.max_value, min_value=self.min_value)
            namespace.assign(self, key, copy)
            # create it as above and register it in namespace
            return copy
        # if you are here, then you found it
        return lookup

    def create_local_representative(
        self,
        context=None,
        local_variable_class=None,
        name="loc",
        autorequire=True,
        **kwargs,
    ):
        """
        Create a local representative variable for the selector.

        :param context: Builder context used for namespace allocation.
        :param local_variable_class: Variable class to instantiate.
        :param name: Temporary base name.
        :param autorequire: Whether the created representative should be
            required by the current container immediately.
        """
        if local_variable_class is None:
            local_variable_class = type(self).local_variable_class
        assert local_variable_class is not None
        if context is None:
            raise ValueError("No context provided")
        self._local = context.namespace.request_temp(
            local_variable_class,
            name=name,
            origin=context.container,
            dtype=self._dtype,
        )
        # this was the old way, that does not allow recycling of temp variables,
        # which would be bad in GPU kernels, where threadId.x needs to map to all
        # self._local = local_variable_class(
        #     namespace=context.namespace,
        #     **kwargs,
        # )
        if autorequire:
            context.container.requires(self.local)
        return self._local

    def create_input_representative(
        self,
        context=None,
        input_variable_class=None,
        autorequire=True,
        **kwargs,
    ):
        """Create an input-style representative for the selector."""
        if input_variable_class is None:
            input_variable_class = type(self).input_variable_class
        assert input_variable_class is not None
        if context is None:
            raise ValueError("No context provided")
        if self._local is None:
            self._local = input_variable_class(
                # assigned_variable=self,
                assignment=(self, None),
                # key=None,
                namespace=context.namespace,
                **kwargs,
            )
        if autorequire:
            context.container.requires(self.local)
        context.namespace.assign(self, None, self.local)
        return self._local

    def as_argument(self) -> str:
        """Return the representative as a routine-call argument."""
        return self.local.as_argument()

    def reset_representative(self) -> None:
        """Discard any created representative variable."""
        self._local = None

    def expr(self) -> str:
        """Return the representative expression for this selector."""
        return f"{self.local.expr()}"

    @property
    def max_value(self):
        """access max value"""
        return self._max_value

    @property
    def min_value(self):
        """access min value"""
        return self._min_value

    @property
    def local(self):
        """access the local representation of the frame selector"""
        return self._local

    @property
    def is_scalar(self):
        """return boolean deciding whether the variable is a scalar"""
        return self._size is None

    @property
    def size(self):
        """access size attribute"""
        return self._size

    @property
    def dtype(self):
        """access datatype attribute"""
        return self.local.dtype

    @property
    def datatype(self):
        """access datatype attribute"""
        return self.local.lookup_dtype(self.dtype)

    @property
    def status(self):
        """access the status binary set as integer"""
        return self.local.status

    def split(self, max_val):
        """
        Split the covered range into two nested multiframe variables.

        :param max_val: Maximum extent that the inner selector may cover.
        :returns: ``(inner_selector, outer_selector)``.
        """
        irange = self.max_value - self.min_value

        div = (irange + max_val - 1) // max_val
        lim = min(irange, max_val)

        first = type(self)(lim, min_value=0)
        second = type(self)(div, min_value=0)
        return first, second


class KernelRequest(LibRoutineMultiFrame):
    """Multiframe-like metadata request emitted by kernel expansion."""

    _VAR_IDENTIFIER = "KernelRequest"
    _CLASS_BASE = "krq"

    def __init__(self, descriptor, max_value, min_value=0, source=None):
        super().__init__(max_value=max_value, min_value=min_value)
        self._source = source
        self._descriptor = descriptor

    @property
    def source(self):
        """Return the request source object, if one was recorded."""
        return self._source

    @property
    def descriptor(self):
        """Return the human-readable descriptor of the request."""
        return self._descriptor
